WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_summarize_measure'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '概括对策', 'kp-sl-summarize-measure', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "归纳概括：对策类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心心法：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "寻找材料中动宾结构的“做法句”。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、找词雷达"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“必须、应该、需要、亟待、要、通过...方式、采取...手段、建立、完善、加强、推进、落实”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、答题结构"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "所有的对策都必须呈现为【强动词 + 核心名词】的结构。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "错误写法：“政府的监管非常重要”。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "正确得分写法：“【加强】政府【监管】”。只有这样的动宾结构，机器和人工阅卷时才能瞬间扫到得分点。"}]}]}$$ AS jsonb), NULL, '概括对策的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "归纳概括", "概括对策"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_summarize_measure", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
